// Should we seal the return types of these traits cause they should only be constructed via the macros.

use std::error;

use crate::Driver;

/// The definitions of a valid SQL selection.
///
/// This is implemented on the model-struct which is generated by the [`#[derive(Table)]`](crate::Table!) attribute and also on selections defined by [`select!`](crate::select!).
pub trait Table: 'static {
    /// The user-defined struct representing a single row in the table.
    /// This is the struct that has the `#[derive(Table)]` applied to it.
    type Model;

    /// A struct representing a new row to be inserted into the table.
    /// This struct is generated by the `#[derive(Table)]` attribute.
    ///
    /// The type in this field should implement [`InsertStruct`].
    /// If it does not you should use [`ModelNotSuitableForSelection`] to improve the compiler hints.
    type Insert;

    /// The name of the table. This is used verbatim in the SQL queries.
    fn name(&self) -> &'static str;

    /// The columns to select when performing a `SELECT *` query on this table.
    fn selection(&self) -> &'static [&'static str];
}

pub enum ModelNotSuitableForSelection {}

pub trait Insertable<D: Driver> {
    fn columns() -> &'static [&'static str];

    fn encode<'a>(
        &self,
        arguments: &mut D::Arguments<'a>,
        column: usize,
    ) -> Result<(), Box<dyn error::Error + Send + Sync + 'static>>;
}
